mapper.select:
select rtsr.rela_id, rtsr.review_id, rtsr.user_id,
(select real_name from auth_info where user_id = rtsr.user_id AND auth_status = '5' order by auth_time desc limit 1) user_name,
rtsr.allot_status, rtsr.review_status, rtsr.create_by, rtsr.create_time, rtsr.update_by,
rtsr.update_time, rtsr.version, rtsr.del_flag
from review_task_specialist_relation rtsr

    rtsr.del_flag = '0'

        and rtsr.review_id = #{reviewId}


        and rtsr.user_id = #{userId}


        and rtsr.allot_status = #{allotStatus}


        and rtsr.review_status = #{reviewStatus}

mapper.update:
update review_task_specialist_relation
review_id = #{reviewId}, user_id = #{userId}, allot_status = #{allotStatus}, review_status = #{reviewStatus}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = #{version}, del_flag = #{delFlag},
where rela_id = #{relaId}

update.foreach:
update review_task_specialist_relation
review_id = #{item.reviewId}, user_id = #{item.userId}, allot_status = #{item.allotStatus}, review_status = #{item.reviewStatus}, create_by = #{item.createBy}, create_time = #{item.createTime}, update_by = #{item.updateBy}, update_time = NOW(), version = version +1,
where rela_id = #{item.relaId}
